sys_script_include.script:
var IncidentInProgressUtils = Class.create();
IncidentInProgressUtils.prototype = {
    initialize: function () {},

    /**
     * Returns an array of {number, short_description} for incidents in "In Progress".
     * Note: Incident state is typically a choice field stored as an integer (often 2 = In Progress).
     */
    getInProgressIncidents: function () {
        var results = [];

        var gr = new GlideRecord('incident');
        gr.addQuery('state', '2'); // "In Progress" is commonly value 2; confirm in your instance if customized
        gr.query();

        while (gr.next()) {
            results.push({
                number: gr.getValue('number'),
                short_description: gr.getValue('short_description')
            });
        }

        return results;
    },

    type: 'IncidentInProgressUtils'
};
